from itertools import islice

def unique_justseen(iterable, key=None):
    """Yields elements in order, ignoring serial duplicates

    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    >>> list(unique_justseen('ABBCcAD', str.lower))
    ['A', 'B', 'C', 'A', 'D']

    """
    if key is None:
        key = lambda x: x

    iterables = [iterable]
    for offset in range(1, len(iterables)):
        iterables.append(islice(iterables[0], offset, None))

    for items in zip(*iterables):
        if any(k(item) != k(prev) for item, prev in zip(items, islice(items, 1))):
            yield items[0]

from itertools import tee, islice

def duplicates_justseen(iterable, key=None):
    """Yields serially-duplicate elements after their first appearance.

    >>> list(duplicates_justseen('mississippi'))
    ['s', 's', 'p']
    >>> list(duplicates_justseen('AaaBbbCccAaa', str.lower))
    ['a', 'a', 'b', 'b', 'c', 'c', 'a', 'a']

    This function is analogous to :func:`unique_justseen`.

    """
    iterables = tee(iterable, 2)
    a, b = iterables
    b = islice(b, 1, None)
    if key is None:
        for x, y in zip(a, b):
            if x == y:
                yield x
    else:
        for x, y in zip(a, b):
            if key(x) == key(y):
                yield x

from itertools import cycle

def roundrobin(*iterables):
    """Visit input iterables in a cycle until each is exhausted.

        >>> list(roundrobin('ABC', 'D', 'EF'))
        ['A', 'D', 'E', 'B', 'F', 'C']

    This function produces the same output as :func:`interleave_longest`, but
    may perform better for some inputs (in particular when the number of
    iterables is small).

    """
    for item in cycle(zip(*iterables)):
        for subitem in item:
            if subitem is not None:
                yield subitem

from itertools import takewhile

def longest_common_prefix(iterables):
    """Yield elements of the longest common prefix among given *iterables*.

    >>> ''.join(longest_common_prefix(['abcd', 'abc', 'abf']))
    'ab'

    """
    if not iterables:
        return

    # Find the shortest iterable
    shortest = min(iterables, key=len)
    for prefix, (iterable, item) in zip(takewhile(None, shortest), zip(iterables, shortest)):
        if all(item == other_item for other_iterable, other_item in zip(iterables, item)):
            yield item
        else:
            break

from itertools import chain, islice

def reshape(matrix, shape):
    """Change the shape of a *matrix*.

    If *shape* is an integer, the matrix must be two dimensional
    and the shape is interpreted as the desired number of columns:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]
        >>> cols = 3
        >>> list(reshape(matrix, cols))
        [(0, 1, 2), (3, 4, 5)]

    If *shape* is a tuple (or other iterable), the input matrix can have
    any number of dimensions. It will first be flattened and then rebuilt
    to the desired shape which can also be multidimensional:

        >>> matrix = [(0, 1), (2, 3), (4, 5)]    # Start with a 3 x 2 matrix

        >>> list(reshape(matrix, (2, 3)))        # Make a 2 x 3 matrix
        [(0, 1, 2), (3, 4, 5)]

        >>> list(reshape(matrix, (6,)))          # Make a vector of length six
        [0, 1, 2, 3, 4, 5]

        >>> list(reshape(matrix, (2, 1, 3, 1)))  # Make 2 x 1 x 3 x 1 tensor
        [(((0,), (1,), (2,)),), (((3,), (4,), (5,)),)]

    Each dimension is assumed to be uniform, either all arrays or all scalars.
    Flattening stops when the first value in a dimension is a scalar.
    Scalars are bytes, strings, and non-iterables.
    The reshape iterator stops when the requested shape is complete
    or when the input is exhausted, whichever comes first.

    """
    flat = chain.from_iterable(matrix)
    if isinstance(shape, int):
        shape = (shape,)

    def flatten(iterable):
        for item in iterable:
            if isinstance(item, (bytes, str)) or not hasattr(item, '__iter__'):
                yield item
            else:
                yield from flatten(item)

    flattened = flatten(flat)

    def reshape_iter(shape):
        if len(shape) == 1:
            for _ in range(shape[0]):
                try:
                    yield next(flattened)
                except StopIteration:
                    break
        else:
            sub_shape = shape[1:]
            sub_len = 1
            for s in sub_shape:
                sub_len *= s
            for _ in range(shape[0]):
                yield tuple(reshape_iter(sub_shape))

    return reshape_iter(shape)
